package com.hospital.smartqueue.doctor.application;
import com.hospital.smartqueue.common.domain.NotFoundException; import com.hospital.smartqueue.common.infrastructure.AuditService; import com.hospital.smartqueue.doctor.domain.Doctor; import com.hospital.smartqueue.doctor.infrastructure.DoctorRepository; import com.hospital.smartqueue.hospital.infrastructure.HospitalRepository; import org.junit.jupiter.api.Test; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class DoctorServiceTest { private final DoctorRepository doctors=mock(DoctorRepository.class); private final HospitalRepository hospitals=mock(HospitalRepository.class); private final AuditService audit=mock(AuditService.class); private final DoctorService service=new DoctorService(doctors,hospitals,audit);
 @Test void registersActiveDoctorByDefault(){UUID h=UUID.randomUUID();when(hospitals.existsById(h)).thenReturn(true);when(doctors.save(any())).thenAnswer(i->i.getArgument(0));assertEquals(Doctor.Status.ACTIVE,service.register(h,"D1","Dr A","Cardiology","R1",null).getStatus());}
 @Test void rejectsStatusChangeOutsideHospital(){UUID h=UUID.randomUUID(),id=UUID.randomUUID();when(doctors.findById(id)).thenReturn(Optional.of(new Doctor(id,UUID.randomUUID(),"D","N","S","R",Doctor.Status.ACTIVE)));assertThrows(NotFoundException.class,()->service.status(h,id,Doctor.Status.INACTIVE));}}
